#!/usr/bin/env python3
"""
benchmark.py

Multi-API LLM benchmark harness using only Python stdlib.
- Supports:
  - /v1/chat/completions (streaming SSE)
  - /v1/responses (streaming SSE)
- Measures:
  - TTFT (time-to-first-non-empty-content-delta)
  - Total response time
- Runs models in parallel with ThreadPoolExecutor
"""

import argparse
import concurrent.futures
import datetime as dt
import json
import os
import socket
import sys
import time
import urllib.error
import urllib.request
import uuid
from typing import Any, Dict, Generator, List, Optional


PROMPT = "Reply with exactly one sentence about the color blue."
DEFAULT_OUTPUT = "benchmark_results.json"
ALLOWED_API_TYPES = {"chat_completions", "responses"}


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description="Benchmark LLM models across Chat Completions and Responses APIs with TTFT measurement."
    )
    parser.add_argument("--config", required=True, help="Path to model config JSON.")
    parser.add_argument("--output", default=DEFAULT_OUTPUT, help=f"Output JSON path (default: {DEFAULT_OUTPUT})")
    parser.add_argument("--timeout", type=float, default=30.0, help="Per-model timeout in seconds (default: 30)")
    parser.add_argument("--workers", type=int, default=1, help="Parallel worker threads (default: 1)")
    return parser.parse_args()


def load_config(config_path: str) -> List[Dict[str, Any]]:
    with open(config_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    if not isinstance(data, dict):
        raise ValueError("Config root must be a JSON object.")
    if "models" not in data:
        raise ValueError('Config must contain a top-level "models" key.')
    if not isinstance(data["models"], list):
        raise ValueError('"models" must be a list.')

    return data["models"]


def now_iso_utc() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat()


def round_ms(value: Optional[float]) -> Optional[float]:
    if value is None:
        return None
    return round(value, 3)


def endpoint_for(api_type: str) -> str:
    if api_type == "chat_completions":
        return "/v1/chat/completions"
    if api_type == "responses":
        return "/v1/responses"
    raise ValueError(f"Unsupported api_type: {api_type}")


def join_url(base_url: str, path: str) -> str:
    return base_url.rstrip("/") + path


def build_payload(model_cfg: Dict[str, Any], prompt: str) -> Dict[str, Any]:
    api_type = model_cfg.get("api_type")
    model_id = model_cfg.get("id")

    if api_type == "chat_completions":
        payload: Dict[str, Any] = {
            "model": model_id,
            "messages": [{"role": "user", "content": prompt}],
            "stream": True,
        }
    elif api_type == "responses":
        payload = {
            "model": model_id,
            "input": prompt,
            "stream": True,
        }
    else:
        raise ValueError(f"Unsupported api_type: {api_type}")

    if "temperature" in model_cfg:
        payload["temperature"] = model_cfg["temperature"]
    if "max_tokens" in model_cfg:
        payload["max_tokens"] = model_cfg["max_tokens"]

    return payload


def build_headers(model_cfg: Dict[str, Any], api_key: str) -> Dict[str, str]:
    base_url = str(model_cfg.get("base_url", "")).lower()
    api_type = model_cfg.get("api_type")

    headers = {
        "Content-Type": "application/json",
        "Accept": "text/event-stream",
    }

    # Generic bearer auth (works for OpenAI-style APIs)
    # Anthropic-style fallback for responses + anthropic host
    if "anthropic.com" in base_url and api_type == "responses":
        headers["x-api-key"] = api_key
        headers["anthropic-version"] = "2023-06-01"
    else:
        headers["Authorization"] = f"Bearer {api_key}"

    return headers


def iter_sse_data_events(response) -> Generator[str, None, None]:
    """
    Parse SSE stream manually.
    Yields each assembled `data:` event payload as a string.
    """
    data_lines: List[str] = []

    for raw_line in response:
        if not raw_line:
            continue

        line = raw_line.decode("utf-8", errors="replace").rstrip("\r\n")

        # Blank line => end of one SSE event
        if line == "":
            if data_lines:
                yield "\n".join(data_lines)
                data_lines = []
            continue

        if line.startswith("data:"):
            data_lines.append(line[len("data:") :].lstrip())
        else:
            # Ignore other SSE fields like "event:", "id:", comments, etc.
            continue

    # Flush any trailing event
    if data_lines:
        yield "\n".join(data_lines)


def extract_delta_text(api_type: str, event_obj: Dict[str, Any]) -> Optional[str]:
    if api_type == "chat_completions":
        choices = event_obj.get("choices")
        if not isinstance(choices, list) or not choices:
            return None
        first = choices[0]
        if not isinstance(first, dict):
            return None
        delta = first.get("delta")
        if not isinstance(delta, dict):
            return None

        content = delta.get("content")
        if isinstance(content, str):
            return content
        if isinstance(content, list):
            # Some APIs may provide structured segments
            parts: List[str] = []
            for item in content:
                if isinstance(item, dict):
                    t = item.get("text")
                    if isinstance(t, str):
                        parts.append(t)
            return "".join(parts) if parts else None
        return None

    if api_type == "responses":
        # Required format from prompt:
        # {"type":"content_block_delta","delta":{"text":"..."}}
        if event_obj.get("type") == "content_block_delta":
            delta = event_obj.get("delta")
            if isinstance(delta, dict):
                txt = delta.get("text")
                if isinstance(txt, str):
                    return txt

        # Optional fallback for other response-style deltas
        if event_obj.get("type") in ("response.output_text.delta", "output_text.delta"):
            d = event_obj.get("delta")
            if isinstance(d, str):
                return d

        return None

    return None


def error_result(
    model_id: str,
    api_type: Optional[str],
    total_ms: float,
    message: str,
) -> Dict[str, Any]:
    return {
        "model_id": model_id,
        "api_type": api_type,
        "status": "error",
        "ttft_ms": None,
        "total_ms": round_ms(total_ms),
        "first_token": None,
        "full_response": None,
        "error": message,
    }


def run_single_model(model_cfg: Dict[str, Any], prompt: str, timeout_s: float) -> Dict[str, Any]:
    model_id = str(model_cfg.get("id", "<unknown-model>"))
    api_type = model_cfg.get("api_type")

    t_start = time.perf_counter()

    try:
        if not isinstance(model_cfg, dict):
            raise ValueError("Model config entry must be an object.")
        if api_type not in ALLOWED_API_TYPES:
            raise ValueError(f'Invalid or unsupported api_type "{api_type}"')
        if "base_url" not in model_cfg:
            raise ValueError('Missing required field "base_url"')
        if "api_key_env" not in model_cfg:
            raise ValueError('Missing required field "api_key_env"')
        if "id" not in model_cfg:
            raise ValueError('Missing required field "id"')

        api_key_env = model_cfg["api_key_env"]
        api_key = os.environ.get(api_key_env)
        if not api_key:
            raise ValueError(f'Environment variable "{api_key_env}" is not set or empty')

        url = join_url(str(model_cfg["base_url"]), endpoint_for(api_type))
        payload = build_payload(model_cfg, prompt)
        headers = build_headers(model_cfg, api_key)
        body = json.dumps(payload).encode("utf-8")

        req = urllib.request.Request(
            url=url,
            data=body,
            headers=headers,
            method="POST",
        )

        first_token: Optional[str] = None
        ttft_ms: Optional[float] = None
        chunks: List[str] = []

        with urllib.request.urlopen(req, timeout=timeout_s) as resp:
            # Stream SSE
            for event_data in iter_sse_data_events(resp):
                if not event_data:
                    continue
                if event_data == "[DONE]":
                    break

                try:
                    event_obj = json.loads(event_data)
                except json.JSONDecodeError as e:
                    raise ValueError(f"SSE JSON parse error: {e.msg} (pos {e.pos})")

                delta_text = extract_delta_text(api_type, event_obj)
                if delta_text is None:
                    continue

                chunks.append(delta_text)

                if first_token is None:
                    stripped = delta_text.strip()
                    if stripped:
                        ttft_ms = (time.perf_counter() - t_start) * 1000.0
                        first_token = stripped.split()[0] if stripped.split() else stripped

        total_ms = (time.perf_counter() - t_start) * 1000.0
        full_response = "".join(chunks).strip()

        if ttft_ms is None:
            raise ValueError("No non-empty content delta received from stream.")

        return {
            "model_id": model_id,
            "api_type": api_type,
            "status": "ok",
            "ttft_ms": round_ms(ttft_ms),
            "total_ms": round_ms(total_ms),
            "first_token": first_token,
            "full_response": full_response,
            "error": None,
        }

    except urllib.error.HTTPError as e:
        total_ms = (time.perf_counter() - t_start) * 1000.0
        body_snippet = ""
        try:
            err_body = e.read().decode("utf-8", errors="replace")
            if err_body:
                body_snippet = f" | {err_body[:500]}"
        except Exception:
            pass
        msg = f"HTTP {e.code}: {e.reason}{body_snippet}"
        return error_result(model_id, api_type, total_ms, msg)

    except urllib.error.URLError as e:
        total_ms = (time.perf_counter() - t_start) * 1000.0
        if isinstance(e.reason, socket.timeout):
            msg = f"Connection timeout after {int(timeout_s * 1000)}ms"
        else:
            msg = f"Connection error: {e.reason}"
        return error_result(model_id, api_type, total_ms, msg)

    except socket.timeout:
        total_ms = (time.perf_counter() - t_start) * 1000.0
        msg = f"Connection timeout after {int(timeout_s * 1000)}ms"
        return error_result(model_id, api_type, total_ms, msg)

    except Exception as e:
        total_ms = (time.perf_counter() - t_start) * 1000.0
        return error_result(model_id, api_type, total_ms, str(e))


def summarize(results: List[Dict[str, Any]]) -> Dict[str, Any]:
    total = len(results)
    ok_results = [r for r in results if r.get("status") == "ok"]
    errors = total - len(ok_results)

    ttft_values = [r["ttft_ms"] for r in ok_results if isinstance(r.get("ttft_ms"), (int, float))]
    avg_ttft = round_ms(sum(ttft_values) / len(ttft_values)) if ttft_values else None

    fastest_model = None
    slowest_model = None
    if ttft_values:
        fastest = min(ok_results, key=lambda r: r["ttft_ms"] if r["ttft_ms"] is not None else float("inf"))
        slowest = max(ok_results, key=lambda r: r["ttft_ms"] if r["ttft_ms"] is not None else float("-inf"))
        fastest_model = fastest["model_id"]
        slowest_model = slowest["model_id"]

    return {
        "total": total,
        "ok": len(ok_results),
        "errors": errors,
        "avg_ttft_ms": avg_ttft,
        "fastest_model": fastest_model,
        "slowest_model": slowest_model,
    }


def run_benchmark(models: List[Dict[str, Any]], timeout_s: float, workers: int) -> List[Dict[str, Any]]:
    if workers < 1:
        workers = 1

    ordered_results: List[Optional[Dict[str, Any]]] = [None] * len(models)

    with concurrent.futures.ThreadPoolExecutor(max_workers=workers) as executor:
        future_to_index = {
            executor.submit(run_single_model, model_cfg, PROMPT, timeout_s): idx
            for idx, model_cfg in enumerate(models)
        }

        for future in concurrent.futures.as_completed(future_to_index):
            idx = future_to_index[future]
            model_cfg = models[idx]
            model_id = str(model_cfg.get("id", "<unknown-model>")) if isinstance(model_cfg, dict) else "<unknown-model>"
            api_type = model_cfg.get("api_type") if isinstance(model_cfg, dict) else None

            try:
                ordered_results[idx] = future.result()
            except Exception as e:
                # Defensive fallback; worker should already catch errors.
                ordered_results[idx] = error_result(
                    model_id=model_id,
                    api_type=api_type,
                    total_ms=0.0,
                    message=f"Unhandled worker exception: {e}",
                )

    return [r for r in ordered_results if r is not None]


def main() -> int:
    args = parse_args()

    if args.timeout <= 0:
        print("Error: --timeout must be > 0", file=sys.stderr)
        return 2
    if args.workers <= 0:
        print("Error: --workers must be >= 1", file=sys.stderr)
        return 2

    try:
        models = load_config(args.config)
    except FileNotFoundError:
        print(f"Error: config file not found: {args.config}", file=sys.stderr)
        return 1
    except json.JSONDecodeError as e:
        print(f"Error: invalid JSON in config ({args.config}): {e}", file=sys.stderr)
        return 1
    except Exception as e:
        print(f"Error loading config: {e}", file=sys.stderr)
        return 1

    run_id = str(uuid.uuid4())
    timestamp = now_iso_utc()

    results = run_benchmark(models=models, timeout_s=args.timeout, workers=args.workers)
    summary = summarize(results)

    report = {
        "run_id": run_id,
        "timestamp": timestamp,
        "prompt": PROMPT,
        "results": results,
        "summary": summary,
    }

    try:
        with open(args.output, "w", encoding="utf-8") as f:
            json.dump(report, f, indent=2, ensure_ascii=False)
    except Exception as e:
        print(f"Error writing output file {args.output}: {e}", file=sys.stderr)
        return 1

    print(f"Benchmark complete. Wrote {args.output}")
    print(
        f"Total={summary['total']} OK={summary['ok']} Errors={summary['errors']} "
        f"AvgTTFT={summary['avg_ttft_ms']}"
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())
